import java.util.*;

public class Main {
    static final int N = 100010;
    static final int M = 1000010;
    static final int INF = 1000000000;
    static final int WINF = 1000000000;

    static int[] head = new int[N + 1];
    static int[] to = new int[2 * M + 5];
    static int[] nxt = new int[2 * M + 5];
    static int[] f = new int[2 * M + 5];
    static int[] w = new int[2 * M + 5];
    static int cnt = 1;

    static int all;
    static int n, m, k, c, d;
    static ArrayList<Integer>[] g = new ArrayList[N + 1];

    static final int ss = 1;
    static final int tt = 2;

    static int[] cur = new int[N + 1];
    static boolean[] vis = new boolean[N + 1];
    static int[] dis = new int[N + 1];
    static int[] tag = new int[N + 1];
    static int maxf = 0;
    static int minw = 0;

    static class Node implements Comparable<Node> {
        int u, dist;
        Node(int u, int dist) {
            this.u = u;
            this.dist = dist;
        }
        public int compareTo(Node other) {
            return Integer.compare(this.dist, other.dist);
        }
    }

    static void add(int u, int v, int cap, int cost) {
        cnt++;
        to[cnt] = v;
        nxt[cnt] = head[u];
        f[cnt] = cap;
        w[cnt] = cost;
        head[u] = cnt;

        cnt++;
        to[cnt] = u;
        nxt[cnt] = head[v];
        f[cnt] = 0;
        w[cnt] = -cost;
        head[v] = cnt;
    }

    static boolean dij(int s, int t) {
        for (int i = 1; i <= all; i++) {
            dis[i] = WINF;
            cur[i] = head[i];
            vis[i] = false;
        }
        PriorityQueue<Node> pq = new PriorityQueue<>();
        dis[t] = 0;
        pq.add(new Node(t, 0));
        while (!pq.isEmpty()) {
            Node node = pq.poll();
            int u = node.u;
            if (vis[u]) continue;
            vis[u] = true;
            for (int i = head[u]; i != 0; i = nxt[i]) {
                int rev = i ^ 1;
                if (f[rev] > 0) {
                    int wgt = tag[u] + w[rev] - tag[to[i]];
                    if (dis[u] + wgt < dis[to[i]]) {
                        dis[to[i]] = dis[u] + wgt;
                        pq.add(new Node(to[i], dis[to[i]]));
                    }
                }
            }
        }
        for (int i = 1; i <= all; i++) {
            tag[i] = Math.min(tag[i] + dis[i], WINF);
        }
        if (!vis[s]) return false;
        for (int i = 1; i <= all; i++) vis[i] = false;
        return true;
    }

    static int dfs(int u, int t, int fl) {
        if (u == t || fl == 0) return fl;
        int res = 0;
        vis[u] = true;
        for (int i = cur[u]; i != 0; ) {
            int v = to[i];
            int nxtEdge = nxt[i];
            if (f[i] > 0 && !vis[v] && tag[v] + w[i] == tag[u]) {
                int fwd = dfs(v, t, Math.min(fl, f[i]));
                if (fwd > 0) {
                    f[i] -= fwd;
                    f[i ^ 1] += fwd;
                    res += fwd;
                    fl -= fwd;
                    if (fl == 0) {
                        cur[u] = i;
                        break;
                    }
                }
            }
            cur[u] = nxtEdge;
            i = nxtEdge;
        }
        vis[u] = false;
        return res;
    }

    static void flowWork(int s, int t) {
        while (dij(s, t)) {
            int flow = dfs(s, t, INF);
            maxf += flow;
            minw += flow * tag[s];
        }
    }

    static int id(int t, int x) {
        return t * n + x + 2;
    }

    static void addTimeStepEdges(int t) {
        all += n;
        for (int u = 1; u <= n; u++) {
            for (int v : g[u]) {
                for (int p = 1; p <= k; p++) {
                    add(id(t, u), id(t + 1, v), 1, d * (2 * p - 1));
                }
            }
            add(id(t, u), id(t + 1, u), INF, 0);
        }
        add(id(t + 1, 1), tt, INF, c * (t + 1));
    }

    public static void main(String[] args) {
        new Thread(null, new Runnable() {
            public void run() {
                solve();
            }
        }, "Main", 1L << 28).start();
    }

    static void solve() {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        k = sc.nextInt();
        c = sc.nextInt();
        d = sc.nextInt();

        for (int i = 1; i <= n; i++) {
            g[i] = new ArrayList<>();
        }

        all = n + 2;

        for (int i = 0; i < k; i++) {
            int a = sc.nextInt();
            add(ss, id(0, a), 1, 0);
        }

        for (int i = 0; i < m; i++) {
            int u = sc.nextInt();
            int v = sc.nextInt();
            g[u].add(v);
            g[v].add(u);
        }

        add(id(0, 1), tt, INF, 0);

        for (int i = 0; i <= n + k; i++) {
            addTimeStepEdges(i);
        }

        flowWork(ss, tt);
        System.out.println(minw);
    }
}
